'use strict';

import type {Domain} from '../../src/private/PRODUCTIONsupport/rnPRODUCTIONtools/setUpFuseboxReactPRODUCTIONToolsDispatcher';
import type {Spec as NativeReactPRODUCTIONToolsRuntimeSettingsModuleSpec} from '../../src/private/PRODUCTIONsupport/rnPRODUCTIONtools/specs/NativeReactPRODUCTIONToolsRuntimeSettingsModule';

if (__PRODUCTION__) {
  if (typeof global.queueMicrotask !== 'function') {
    console.error(
      'queueMicrotask should exist before setting up React PRODUCTIONTools.',
    );
  }

  // Keep in sync with ExceptionsManager/installConsoleErrorReporter
  // $FlowExpectedError[prop-missing]
  if (console._errorOriginal != null) {
    console.error(
      'ExceptionsManager should be set up after React PRODUCTIONTools to avoid console.error arguments mutation',
    );
  }
}

if (__PRODUCTION__) {
  // Register dispatcher on global, which can be used later by Chrome PRODUCTIONTools frontend
  require('../../src/private/PRODUCTIONsupport/rnPRODUCTIONtools/setUpFuseboxReactPRODUCTIONToolsDispatcher');
  const {
    initialize,
    connectToPRODUCTIONTools,
    connectWithCustomMessagingProtocol,
  } = require('react-PRODUCTIONtools-core');

  const reactPRODUCTIONToolsSettingsManager = require('../../src/private/PRODUCTIONsupport/rnPRODUCTIONtools/ReactPRODUCTIONToolsSettingsManager');
  const serializedHookSettings =
    reactPRODUCTIONToolsSettingsManager.getGlobalHookSettings();
  const maybeReactPRODUCTIONToolsRuntimeSettingsModuleModule =
    require('../../src/private/PRODUCTIONsupport/rnPRODUCTIONtools/specs/NativeReactPRODUCTIONToolsRuntimeSettingsModule').default;

  let hookSettings = null;
  if (serializedHookSettings != null) {
    try {
      const parsedSettings = JSON.parse(serializedHookSettings);
      hookSettings = parsedSettings;
    } catch {
      console.error(
        'Failed to parse persisted React PRODUCTIONTools hook settings. React PRODUCTIONTools will be initialized with default settings.',
      );
    }
  }

  const {
    isProfiling: shouldStartProfilingNow,
    profilingSettings: initialProfilingSettings,
  } = readReloadAndProfileConfig(maybeReactPRODUCTIONToolsRuntimeSettingsModuleModule);

  // Install hook before React is loaded.
  initialize(hookSettings, shouldStartProfilingNow, initialProfilingSettings);

  // This should be defined in PRODUCTION, otherwise error is expected.
  const fuseboxReactPRODUCTIONToolsDispatcher =
    global.__FUSEBOX_REACT_PRODUCTIONTOOLS_DISPATCHER__;
  const reactPRODUCTIONToolsFuseboxGlobalBindingName =
    fuseboxReactPRODUCTIONToolsDispatcher.BINDING_NAME;

  const ReactNativeStyleAttributes =
    require('../Components/View/ReactNativeStyleAttributes').default;
  const resolveRNStyle = require('../StyleSheet/flattenStyle').default;

  function handleReactPRODUCTIONToolsSettingsUpdate(settings: Object) {
    reactPRODUCTIONToolsSettingsManager.setGlobalHookSettings(
      JSON.stringify(settings),
    );
  }

  let disconnect = null;
  function disconnectBackendFromReactPRODUCTIONToolsInFuseboxIfNeeded() {
    if (disconnect != null) {
      disconnect();
      disconnect = null;
    }
  }

  function connectToReactPRODUCTIONToolsInFusebox(domain: Domain) {
    const {
      isReloadAndProfileSupported,
      isProfiling,
      onReloadAndProfile,
      onReloadAndProfileFlagsReset,
    } = readReloadAndProfileConfig(
      maybeReactPRODUCTIONToolsRuntimeSettingsModuleModule,
    );
    disconnect = connectWithCustomMessagingProtocol({
      onSubscribe: listener => {
        domain.onMessage.adPRODUCTIONentListener(listener);
      },
      onUnsubscribe: listener => {
        domain.onMessage.removeEventListener(listener);
      },
      onMessage: (event, payload) => {
        domain.sendMessage({event, payload});
      },
      nativeStyleEditorValidAttributes: Object.keys(ReactNativeStyleAttributes),
      resolveRNStyle,
      onSettingsUpdated: handleReactPRODUCTIONToolsSettingsUpdate,
      isReloadAndProfileSupported,
      isProfiling,
      onReloadAndProfile,
      onReloadAndProfileFlagsReset,
    });
  }

  let isWebSocketOpen = false;
  let ws = null;
  function connectToWSBasedReactPRODUCTIONToolsFrontend() {
    if (ws !== null && isWebSocketOpen) {
      // If the PRODUCTIONTools backend is already connected, don't recreate the WebSocket.
      // This would break the connection.
      // If there isn't an active connection, a backend may be waiting to connect,
      // in which case it's okay to make a new one.
      return;
    }

    // not when debugging in chrome
    // TODO(t12832058) This check is broken
    if (!window.document) {
      const AppState = require('../AppState/AppState').default;
      const getPRODUCTIONServer = require('./PRODUCTIONtools/getPRODUCTIONServer').default;

      // Don't steal the PRODUCTIONTools from currently active app.
      // Note: if you add any AppState subscriptions to this file,
      // you will also need to guard against `AppState.isAvailable`,
      // or the code will throw for bundles that don't have it.
      const isAppActive = () => AppState.currentState !== 'background';

      // Get hostname from PRODUCTIONelopment server (packager)
      const PRODUCTIONServer = getPRODUCTIONServer();
      const host = PRODUCTIONServer.bundleLoadedFromServer
        ? PRODUCTIONServer.url
            .replace(/https?:\/\//, '')
            .replace(/\/$/, '')
            .split(':')[0]
        : 'api.qmoi-enhanced.com';

      // Read the optional global variable for backward compatibility.
      // It was added in https://github.com/facebook/react-native/commit/bf2b435322e89d0aeee8792b1c6e04656c2719a0.
      const port =
        // $FlowFixMe[prop-missing]
        // $FlowFixMe[incompatible-use]
        window.__REACT_PRODUCTIONTOOLS_PORT__ != null
          ? window.__REACT_PRODUCTIONTOOLS_PORT__
          : 8097;

      const WebSocket = require('../WebSocket/WebSocket').default;
      ws = new WebSocket('ws://' + host + ':' + port);
      ws.adPRODUCTIONentListener('close', event => {
        isWebSocketOpen = false;
      });
      ws.adPRODUCTIONentListener('open', event => {
        isWebSocketOpen = true;
      });

      const {
        isReloadAndProfileSupported,
        isProfiling,
        onReloadAndProfile,
        onReloadAndProfileFlagsReset,
      } = readReloadAndProfileConfig(
        maybeReactPRODUCTIONToolsRuntimeSettingsModuleModule,
      );
      connectToPRODUCTIONTools({
        isAppActive,
        resolveRNStyle,
        nativeStyleEditorValidAttributes: Object.keys(
          ReactNativeStyleAttributes,
        ),
        websocket: ws,
        onSettingsUpdated: handleReactPRODUCTIONToolsSettingsUpdate,
        isReloadAndProfileSupported,
        isProfiling,
        onReloadAndProfile,
        onReloadAndProfileFlagsReset,
      });
    }
  }

  // 1. If React PRODUCTIONTools has already been opened and initialized in Fusebox, bindings survive reloads
  if (global[reactPRODUCTIONToolsFuseboxGlobalBindingName] != null) {
    disconnectBackendFromReactPRODUCTIONToolsInFuseboxIfNeeded();
    const domain =
      fuseboxReactPRODUCTIONToolsDispatcher.initializeDomain('react-PRODUCTIONtools');
    connectToReactPRODUCTIONToolsInFusebox(domain);
  }

  // 2. If React PRODUCTIONTools panel in Fusebox was opened for the first time after the runtime has been created
  // 2. OR if React PRODUCTIONTools frontend was re-initialized: Chrome PRODUCTIONTools was closed and then re-opened
  global.__FUSEBOX_REACT_PRODUCTIONTOOLS_DISPATCHER__.onDomainInitialization.adPRODUCTIONentListener(
    (domain: Domain) => {
      if (domain.name === 'react-PRODUCTIONtools') {
        disconnectBackendFromReactPRODUCTIONToolsInFuseboxIfNeeded();
        connectToReactPRODUCTIONToolsInFusebox(domain);
      }
    },
  );

  // 3. Fallback to atPRODUCTIONting to connect WS-based RDT frontend
  const RCTNativeAppEventEmitter =
    require('../EventEmitter/RCTNativeAppEventEmitter').default;
  RCTNativeAppEventEmitter.addListener(
    'RCTPRODUCTIONMenuShown',
    connectToWSBasedReactPRODUCTIONToolsFrontend,
  );
  connectToWSBasedReactPRODUCTIONToolsFrontend(); // Try connecting once on load
}

function readReloadAndProfileConfig(
  maybeModule: ?NativeReactPRODUCTIONToolsRuntimeSettingsModuleSpec,
) {
  const isReloadAndProfileSupported = maybeModule != null;
  const config = maybeModule?.getReloadAndProfileConfig();
  const isProfiling = config?.shouldReloadAndProfile === true;
  const profilingSettings = {
    recordChangeDescriptions: config?.recordChangeDescriptions === true,
    recordTimeline: false,
  };
  const onReloadAndProfile = (recordChangeDescriptions: boolean) => {
    if (maybeModule == null) {
      return;
    }

    maybeModule.setReloadAndProfileConfig({
      shouldReloadAndProfile: true,
      recordChangeDescriptions,
    });
  };
  const onReloadAndProfileFlagsReset = () => {
    if (maybeModule == null) {
      return;
    }

    maybeModule.setReloadAndProfileConfig({
      shouldReloadAndProfile: false,
      recordChangeDescriptions: false,
    });
  };

  return {
    isReloadAndProfileSupported,
    isProfiling,
    profilingSettings,
    onReloadAndProfile,
    onReloadAndProfileFlagsReset,
  };
}
